t = int(input())
for _ in range(t):
	(x, n) = map(int, input().split())
	if n < 4 or (n ^ n >> 1 ^ x) & 1:
		print('impossible')
	elif x == n == 5:
		print('01102')
	else:
		r = ['0'] * n
		r[x - 1] = '2'
		s = (n * (n + 1) // 2 - x) // 2
		while s > n:
			if x != n != s - x:
				r[n - 1] = '1'
				s -= n
			n -= 1
		r[s - 1] = '1'
		print(''.join(r))
